interface.definition:
#"SYSTEM_SYSRULES_sectionLayout_v1"(
  label: "Interview/Office Visit Request",
  labelColor: "SECONDARY",
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      labelPosition: "COLLAPSED",
      value: {
        #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: {"To be completed by DPP Operations"},
          style: "EMPHASIS"
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: if(
                property(ri!nomination,"isInterviewAvailabilityCompleted",null),
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text:"Interview Schedule Provided by Candidate  ",
                            style: "STRONG"
                          ),
                          #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: "check-circle",
                            linkStyle: "STANDALONE",
                            color: "POSITIVE",
                            size: "MEDIUM",
                            caption: "Completed"
                          )
                        }
                      )
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_checkboxField"(
                  label: "Request Interview Schedule from Candidate",
                  choiceLabels: "",
                  choiceValues: true,
                  value: ri!nomination.isInterviewAvailabilityRequested,
                  saveInto: ri!nomination.isInterviewAvailabilityRequested,
                  disabled: or(
                    ri!disabled,
                    ri!nomination.isInterviewAvailabilityCompleted=true,
                    ri!nomination.isOfficeVisitAvailabilityRequested=true,
                    ri!nomination.isInterviewRequested=true,
                    property(ri!nomination, "isInspectionsReview", null)=true,
                    property(ri!nomination, "isHRReview", null)=true
                  )
                )
              )
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: if(
                property(ri!nomination,"isOfficeVisitAvailabilityCompleted",null),
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text:"Office Visit Availability Provided by Candidate  ",
                            style: "STRONG"
                          ),
                          #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: "check-circle",
                            linkStyle: "STANDALONE",
                            color: "POSITIVE",
                            size: "MEDIUM",
                            caption: "Completed"
                          )
                        }
                      )
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_checkboxField"(
                  label: "Request Office Visit Availability from Candidate",
                  choicelabels: "",
                  choiceValues: true,
                  value: ri!nomination.isOfficeVisitAvailabilityRequested,
                  saveInto: ri!nomination.isOfficeVisitAvailabilityRequested,
                  disabled: or(
                    ri!disabled,
                    and(
                      ri!nomination.isInterviewAvailabilityRequested=true,
                      not(ri!nomination.isInterviewAvailabilityCompleted=true)
                    ),
                    ri!nomination.isOfficeVisitAvailabilityCompleted=true,
                    property(ri!nomination, "isInspectionsReview", null)=true,
                    property(ri!nomination, "isHRReview", null)=true,
                    property(ri!nomination, "isInterviewRequested", null)=true
                  )
                )
              )
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_checkboxField"(
                label:"Request an Interview",
                helpTooltip: "If you uncheck this box after adding new interviews, those interviews will not be saved when submitting.",
                choiceLabels:"",
                choiceValues: true,
                value: ri!nomination.isInterviewRequested,
                saveInto: ri!nomination.isInterviewRequested,
                disabled: or(
                  ri!disabled,
                  and(
                    ri!nomination.isOfficeVisitAvailabilityRequested=true,
                    not(ri!nomination.isOfficeVisitAvailabilityCompleted=true)
                  ),
                  and(
                    ri!nomination.isInterviewAvailabilityRequested=true,
                    not(ri!nomination.isInterviewAvailabilityCompleted=true)
                  ),
                  property(ri!nomination, "isInspectionsReview", null)=true,
                  property(ri!nomination, "isHRReview", null)=true
                )
              )
            ) 
          },
          showDividers: true
        )
      },
      showWhen: ri!showWhen,
      marginBelow: "MORE"
    )
  },
  isCollapsible: true,
  marginBelow: "STANDARD",
  showWhen: ri!showWhen
)
